def _internal_test_script() -> str:
    return """import { readFileSync, existsSync } from "node:fs";

const requiredFiles = [
  "src/App.tsx",
  "src/data/worlds.ts",
  "src/engine/safety.ts",
  "src/engine/spark.ts",
  "src/engine/storage.ts",
  "docs/interaction-design.md",
  "docs/internal-playtest-plan.md",
];

for (const file of requiredFiles) {
  if (!existsSync(file)) throw new Error(`Missing required file: ${file}`);
}

const app = readFileSync("src/App.tsx", "utf8");
const worlds = readFileSync("src/data/worlds.ts", "utf8");
const storage = readFileSync("src/engine/storage.ts", "utf8");
const packageJson = JSON.parse(readFileSync("package.json", "utf8"));

const checks = [
  ["gameful package", packageJson.name === "huohutu-spark-gameful-playtest"],
  ["game board", app.includes("gameBoard") && app.includes("worldStage")],
  ["action cards", app.includes("actionCard") && app.includes("playMove")],
  ["inventory tokens", app.includes("tokenShelf") && app.includes("progress.tokens")],
  ["quest progress", app.includes("questMeter") && app.includes("questProgress")],
  ["crafting mechanic", worlds.includes("requiredTokens") && worlds.includes("addsObjects")],
  ["not text echo demo", !app.includes("把孩子的词语变成")],
  ["parent spark book", app.includes("家长火花册")],
  ["internal game route", app.includes("游戏性内测")],
  ["safety redirect", app.includes("安全重定向")],
  ["user simulation script", packageJson.scripts["test:user-sim"] === "node scripts/user-sim.mjs"],
  ["world-specific feedback", app.includes("latestActiveWorldEvent") && app.includes("activeWorldEvents")],
  ["fresh storage namespace", storage.includes("huohutu.spark.gameful.snapshot.v4")],
];

const failed = checks.filter(([, ok]) => !ok).map(([name]) => name);
if (failed.length) throw new Error(`Internal game checks failed: ${failed.join(", ")}`);

console.log(JSON.stringify({ ok: true, checks: checks.map(([name]) => name) }, null, 2));
"""


def _user_sim_script() -> str:
    return """import { readFileSync } from "node:fs";

const app = readFileSync("src/App.tsx", "utf8");
const worlds = readFileSync("src/data/worlds.ts", "utf8");
const styles = readFileSync("src/styles.css", "utf8");

const checks = [
  ["first-run game goal", app.includes("今天的目标") && app.includes("开始冒险")],
  ["child can play without typing", app.includes("playMove(move)")],
  ["visible world changes", app.includes("stageObject") && app.includes("unlockedObjects")],
  ["success and blocked feedback", app.includes("还差") && app.includes("完成")],
  ["two different game loops", worlds.includes("彩虹造物岛") && worlds.includes("故事星球")],
  ["collection loop", worlds.includes("addsTokens")],
  ["craft loop", worlds.includes("requiredTokens")],
  ["quest win state", app.includes("任务完成") && app.includes("下一步")],
  ["parent value beyond chart", app.includes("阶段性纪念") && app.includes("孩子的火花线索")],
  ["large tablet-first board", styles.includes(".worldStage") && styles.includes(".actionDock")],
  ["internal tester can run scenarios", app.includes("runScenario") && app.includes("gameplayChecks")],
  ["world switch does not leak stale feedback", app.includes("activeWorldEvents") && app.includes("latestActiveWorldEvent")],
];

const failed = checks.filter(([, ok]) => !ok).map(([name]) => name);
if (failed.length) throw new Error(`User simulation checks failed: ${failed.join(", ")}`);

console.log(JSON.stringify({ ok: true, simulatedPersonas: ["new-child-player", "parent-reviewer", "internal-game-tester"], checks: checks.map(([name]) => name) }, null, 2));
"""


def _types_ts() -> str:
    return """export type AgeBand = "2-4" | "5-6" | "7-9";
export type SparkKey = "expression" | "creativity" | "story" | "science" | "social" | "nature" | "aiCollaboration";
export type WorldId = "rainbow-island" | "story-planet";
export type MoveKind = "collect" | "craft" | "help" | "ask" | "comfort" | "free";
export type SafetyLevel = "safe" | "redirected";

export interface GameMove {
  id: string;
  title: string;
  kind: MoveKind;
  phrase: string;
  result: string;
  requiredTokens: string[];
  addsTokens: string[];
  addsObjects: string[];
  sparkTags: SparkKey[];
  questDelta: number;
}

export interface WorldDefinition {
  id: WorldId;
  name: string;
  shortName: string;
  gameGoal: string;
  companion: string;
  companionRole: string;
  palette: { sky: string; ground: string; accent: string; ink: string };
  startingObjects: string[];
  moves: GameMove[];
  playtestScenarioIds: string[];
  sparkBias: SparkKey[];
}

export interface GameProgress {
  questProgress: number;
  tokens: string[];
  unlockedObjects: string[];
  completedMoveIds: string[];
  badges: string[];
}

export interface SparkScores {
  expression: number;
  creativity: number;
  story: number;
  science: number;
  social: number;
  nature: number;
  aiCollaboration: number;
}

export interface ChildEvent {
  id: string;
  at: string;
  worldId: WorldId;
  ageBand: AgeBand;
  moveId: string;
  childInput: string;
  result: string;
  safetyLevel: SafetyLevel;
  sparkTags: SparkKey[];
  tokens: string[];
  objects: string[];
}

export interface GameSnapshot {
  activeWorldId: WorldId;
  ageBand: AgeBand;
  progress: Record<WorldId, GameProgress>;
  sparkScores: SparkScores;
  events: ChildEvent[];
  cloudSyncEnabled: boolean;
}
"""


